#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <stdio.h>
#include <errno.h>

#define TARGET_FILE "/etc/passwd"

int main() {
    struct stat file_stats;

    // Attempt to retrieve status information for TARGET_FILE
    if (stat(TARGET_FILE, &file_stats) == -1) {
        perror("Error calling stat");
        if (errno == ENOENT) {
            fprintf(stderr, "File %s not found.\n", TARGET_FILE);
        }
        return 1;
    }

    printf("Status retrieved for %s:\n", TARGET_FILE);
    printf("  File Size: %ld bytes\n", (long)file_stats.st_size);
    printf("  Inode Number: %lu\n", (unsigned long)file_stats.st_ino);

    // Check if the file is a regular file
    if (S_ISREG(file_stats.st_mode)) {
        printf("  Type: Regular File\n");
    } else if (S_ISDIR(file_stats.st_mode)) {
        printf("  Type: Directory\n");
    } else if (S_ISLNK(file_stats.st_mode)) {
        printf("  Type: Symbolic Link\n");
    } else {
        printf("  Type: Other\n");
    }

    // Print basic permissions (Owner Read/Write/Execute)
    printf("  Permissions (Owner): %s%s%s\n",
           (file_stats.st_mode & S_IRUSR) ? "r" : "-",
           (file_stats.st_mode & S_IWUSR) ? "w" : "-",
           (file_stats.st_mode & S_IXUSR) ? "x" : "-");

    return 0;
}
